package main

import (
	"bytes"
	"text/template"
)

// generateCheckSource returns the source of the generated test of tela
// check and tela verify: for each preview and variant of the spec it mounts
// the screen as tela snapshot does and runs telatest's audit (ADR-306,
// ADR-312), writing the violations as JSON. Like the other generated files
// it imports only public packages, and its names are aliased.
func generateCheckSource(pkgName string, c contract, hasApp bool, feats genFeatures) []byte {
	var buf bytes.Buffer
	err := checkGenTemplate.Execute(&buf, struct {
		Package  string
		Kind     string
		HasApp   bool
		I18N     bool
		DevTools bool
		Env      map[string]string
	}{
		Package: pkgName, Kind: c.String(), HasApp: hasApp, I18N: feats.I18N, DevTools: feats.DevTools,
		Env: map[string]string{"Spec": envSpec, "W": envW, "H": envH, "SizeSet": envSizeSet, "Preview": envPreview,
			"Out": envOut, "Err": envErr, "Log": envLog},
	})
	if err != nil {
		panic(err) // the template is a constant
	}
	return buf.Bytes()
}

var checkGenTemplate = template.Must(template.New("check").Parse(`// Code generated by "tela"; DO NOT EDIT.

package {{.Package}}

import (
	telafmt "fmt"
	telaos "os"
	teladebug "runtime/debug"
	telastrconv "strconv"
	telatesting "testing"

	telajson "encoding/json"
	telasort "sort"
	telastrings "strings"
	telatime "time"

	telatela "github.com/kuronosu/tela"
	telah "github.com/kuronosu/tela/h"
{{- if .I18N}}
	telai18n "github.com/kuronosu/tela/i18n"
{{- end}}
	telatest "github.com/kuronosu/tela/telatest"
)

var (
	_ = telasort.Strings
	_ = telastrings.Join
	_ = telatime.Second
	_ = teladebug.Stack
	_ = telah.Div
)

{{template "contract" .}}
// telaTB is the testing.TB the screens are mounted with: the real test's,
// except that what telatest logs goes to standard error (the dev
// messages as they are, the rest after "tela: ").
type telaTB struct{ telatesting.TB }

func (b telaTB) Logf(format string, args ...any) {
	msg := telafmt.Sprintf(format, args...)
	switch {
	case telastrings.HasPrefix(msg, "dev message: "), telastrings.HasPrefix(msg, "dev warning: "):
		msg = msg[telastrings.Index(msg, ": ")+2:]
	case telastrings.HasPrefix(msg, "telatest: the app was still requesting frames"):
		msg = "tela: warning: the screen never goes quiet (an endless animation, or state that is set all the time); it is shown at its frame after a few seconds"
	default:
		msg = "tela: " + msg
	}
	telafmt.Fprintln(telaos.Stderr, msg)
}

// telaVariant and telaSpec are what tela check asks for (check.go).
type telaVariant struct {
	Name      string  ` + "`json:\"name\"`" + `
	Dark      bool    ` + "`json:\"dark\"`" + `
	Width     float64 ` + "`json:\"width\"`" + `
	TextScale float64 ` + "`json:\"textScale\"`" + `
	RTL       bool    ` + "`json:\"rtl\"`" + `
	Lang      string  ` + "`json:\"lang\"`" + `
	Focus     bool    ` + "`json:\"focus\"`" + `
}

type telaSpec struct {
	All      bool          ` + "`json:\"all\"`" + `
	Variants []telaVariant ` + "`json:\"variants\"`" + `
	Rules    []string      ` + "`json:\"rules\"`" + `
	Disable  []string      ` + "`json:\"disable\"`" + `
}

type telaResult struct {
	Preview    string                ` + "`json:\"preview\"`" + `
	Variant    string                ` + "`json:\"variant\"`" + `
	Skipped    string                ` + "`json:\"skipped,omitempty\"`" + `
	Violations []telatest.Violation ` + "`json:\"violations\"`" + `
}

// telaDirection mounts root under an h.Dir (a display: contents element,
// so the layout is the same but for the direction). A preview keeps its
// Theme and ColorScheme.
func telaDirection(root telatela.Component, dir string) telatela.Component {
	around := func(n telatela.Node) telatela.Node {
		return telah.Div(telah.Dir(dir), telah.Class("contents"), n)
	}
	if p, ok := root.(telatela.Preview); ok {
		wrap := p.Wrap
		p.Wrap = func(n telatela.Node) telatela.Node {
			if wrap != nil {
				n = wrap(n)
			}
			return around(n)
		}
		return p
	}
	return telatela.Preview{Root: root, Wrap: around}
}
{{- if .I18N}}

// telaLocale switches tela/i18n to a locale, or says why not. It returns
// the locale it was in and the one it switched to.
func telaLocale(want string) (prev, tag string, skip string) {
	cur := telai18n.Locale()
	base := func(tag string) string {
		if i := telastrings.IndexAny(tag, "-_"); i >= 0 {
			tag = tag[:i]
		}
		return telastrings.ToLower(tag)
	}
	tag = want
	if tag == "*" {
		tag = ""
		// The first locale of another language than the one in use.
		for _, l := range telai18n.Locales() {
			if base(l) != base(cur) {
				tag = l
				break
			}
		}
		if tag == "" {
			return cur, "", "the package has only one language (tela/i18n); pass --lang TAG to try another"
		}
	}
	func() {
		defer func() {
			if r := recover(); r != nil {
				skip = telafmt.Sprintf("cannot switch to locale %q: %v", tag, r)
			}
		}()
		telai18n.SetLocale(tag)
	}()
	return cur, tag, skip
}
{{- end}}

func TestTelaRun(t *telatesting.T) {
	getenv := func(name string) string { return telaos.Getenv(name) }
	if f, err := telaos.Create(getenv({{printf "%q" .Env.Log}})); err == nil {
		stderr := telaos.Stderr
		telaos.Stderr = f
		defer func() { telaos.Stderr = stderr; f.Close() }()
	}
	fail := func(format string, args ...any) {
		telaos.WriteFile(getenv({{printf "%q" .Env.Err}}), []byte(telafmt.Sprintf(format, args...)), 0o644)
		t.Fatalf(format, args...)
	}
	var spec telaSpec
	if err := telajson.Unmarshal([]byte(getenv({{printf "%q" .Env.Spec}})), &spec); err != nil {
		fail("bad check spec: %v", err)
	}
	num := func(name string) float64 {
		v, err := telastrconv.ParseFloat(getenv(name), 64)
		if err != nil {
			t.Fatalf("%s is not a number: %v", name, err)
		}
		return v
	}
	baseW, baseH := num({{printf "%q" .Env.W}}), num({{printf "%q" .Env.H}})
	sizeSet := getenv({{printf "%q" .Env.SizeSet}}) == "true"
	_ = sizeSet
{{- if .HasApp}}
	if telaHasApp && !sizeSet && telaApp.Width > 0 && telaApp.Height > 0 {
		baseW, baseH = float64(telaApp.Width), float64(telaApp.Height)
	}
{{- end}}

	// The rules: all of them, as the spec narrows them.
	var rules []string
	for _, r := range telatest.Rules() {
		if len(spec.Rules) > 0 {
			ok := false
			for _, id := range spec.Rules {
				ok = ok || id == r.ID
			}
			if !ok {
				continue
			}
		}
		skip := false
		for _, id := range spec.Disable {
			skip = skip || id == r.ID
		}
		if !skip {
			rules = append(rules, r.ID)
		}
	}

	// The previews.
	_, first, names, err := telaBuildNames(getenv({{printf "%q" .Env.Preview}}))
	if err != nil {
		fail("%v", err)
	}
	previews := []string{first}
	if spec.All && len(names) > 0 {
		previews = names
	}

	out := struct {
		Names   []string     ` + "`json:\"names\"`" + `
		Results []telaResult ` + "`json:\"results\"`" + `
	}{Names: names, Results: []telaResult{}}

	for _, name := range previews {
		for _, v := range spec.Variants {
			res := telaResult{Preview: name, Variant: v.Name}
			func() {
				defer func() {
					if r := recover(); r != nil {
						fail("the UI panicked in %s%s: %v\n%s", name, v.Name, r, teladebug.Stack())
					}
				}()
				res.Skipped = telaVariantRun(t, name, v, baseW, baseH, sizeSet, rules, &res)
			}()
			out.Results = append(out.Results, res)
		}
	}
	js, err := telajson.Marshal(out)
	if err != nil {
		t.Fatal(err)
	}
	if err := telaos.WriteFile(getenv({{printf "%q" .Env.Out}}), js, 0o644); err != nil {
		t.Fatal(err)
	}
}

// telaBuildNames is telaBuild for the names alone.
func telaBuildNames(want string) (telatela.Component, string, []string, error) {
	return telaBuild(want)
}

// telaVariantRun mounts preview name as variant v says and audits it; it
// returns why the variant does not apply, or "".
func telaVariantRun(t *telatesting.T, name string, v telaVariant, baseW, baseH float64, sizeSet bool, rules []string, res *telaResult) (skipped string) {
	root, _, _, err := telaBuild(name)
	if err != nil {
		t.Fatalf("%v", err)
	}
	w, h := baseW, baseH
	if v.Width > 0 {
		w = v.Width
	}
	opts := []telatest.Option{telatest.AllowDev(""), telatest.Timeout(5 * telatime.Second)}
{{- if .DevTools}}
	opts = append(opts, telatest.Instrument())
{{- end}}
{{- if .HasApp}}
	scheme, schemeOf := telatela.System, ""
	if telaHasApp {
		opts = append(opts, telatest.FromApp(telaApp))
		scheme, schemeOf = telaApp.ColorScheme, "App.ColorScheme"
	}
{{- else}}
	scheme, schemeOf := telatela.System, ""
{{- end}}
	opts = append(opts, telatest.Size(float32(w), float32(h)))
	if p, ok := root.(telatela.Preview); ok && p.ColorScheme != telatela.System {
		scheme, schemeOf = p.ColorScheme, telafmt.Sprintf("the ColorScheme of preview %q", name)
	}
	// A fixed color scheme is one screen: the variant that is not it
	// repeats the other.
	switch {
	case scheme == telatela.Light && v.Dark, scheme == telatela.Dark && !v.Dark && v.Name == "light":
		return "the color scheme is fixed (" + schemeOf + "), so this variant would repeat the other"
	}
	if scheme == telatela.System && v.Dark {
		opts = append(opts, telatest.Dark())
	}
	if v.TextScale > 0 {
		opts = append(opts, telatest.TextScale(v.TextScale))
	}
	if v.RTL {
		root = telaDirection(root, "rtl")
	}
	if v.Lang != "" {
{{- if .I18N}}
		prev, tag, why := telaLocale(v.Lang)
		if why != "" {
			return why
		}
		defer telai18n.SetLocale(prev)
		res.Variant = "lang " + tag
{{- else}}
		return "the package does not import tela/i18n"
{{- end}}
	}
	app := telatest.Mount(telaTB{t}, root, opts...)
	defer app.Close()
	var ids []string
	for _, id := range rules {
		if id == "focus-visible" && !v.Focus {
			continue
		}
		ids = append(ids, id)
	}
	if len(ids) > 0 {
		res.Violations = app.Audit(telatest.WithRules(ids...))
	}
	if res.Violations == nil {
		res.Violations = []telatest.Violation{}
	}
	return ""
}
` + contractTemplate))
